from lib import *
S = SS('p69')
steps = [
    step("一个页面里 17 种写法的链接,三种“挑链接”的办法:A 用 lxml 解析静态 HTML 取全部 a[href];B 在 A 之上用正则过滤内联 style 和 hidden 属性;C 用 Chrome 加载后用 checkVisibility 加位置尺寸判断。对 display:none、visibility:hidden、opacity:0、hidden 属性、宽高为 0、移到屏幕外(left:-9999px)、font-size:0、父元素 display:none 这 8 种写法:A 全部跟进,B 和 C 都不跟进。对 text_same_color(文字和背景同色)三种办法都跟进;对外部样式表里的类(ext_css_class)、页面脚本加载后才隐藏的(js_hidden)、noscript 里的链接,A 和 B 跟进、C 不跟进。js_created(脚本 0.3 秒后创建的链接)只有 C 看得到。HTML 注释里的链接三种办法都不是链接。", t=tl(S(1)), done=lidx(S(1), 'display_none'), mark=lidx(S(1), 'text_same_color'), b=bars([['A 静态全取:跟进的隐藏链接', 13, '13'], ['B 静态+内联过滤', 5, '5'], ['C Chrome 可见性', 1, '1']], 14, mark=[0], done=[2]), kv=KV([['内联样式隐藏的', 'B、C 都不跟进'], ['外部 CSS / 脚本隐藏的', 'B 看不出,C 看得出'], ['文字与背景同色', '三种办法都会跟进']], ['文字与背景同色'])),
    step("汇总:人眼看不到的 13 种链接里,A 全部跟进(13/13),B 跟进 5 个(ext_css_class、js_hidden、noscript、skip_link、text_same_color),C 只跟进 1 个(text_same_color)。人眼看得到的 3 种里,A 和 B 漏掉 1 个(js_created,静态 HTML 里没有),C 一个不漏。另一面:C 没有跟进 skip_link——这是网页无障碍用的“跳到正文”链接,平时挪到屏幕外、键盘聚焦才出现,属于正常链接,按“可见”过滤会漏掉它。静态 HTML 里有 15 个 a[href]、Chrome 里也是 15 个(静态多了 noscript 里的,Chrome 多了 js_created)。", t=tl(S(2)), done=lidx(S(2), 'C Chrome 可见性'), mark=lidx(S(2), 'A 静态全取'), b=bars([['A:跟进的隐藏链接', 13, '13'], ['B:跟进的隐藏链接', 5, '5'], ['C:跟进的隐藏链接', 1, '1'], ['C:漏掉的正常链接(skip_link 不计入“可见”)', 0, '0']], 14, mark=[0], done=[2]), kv=KV([['A 静态全取', '跟进 13/13,漏 js_created'], ['B 静态+内联过滤', '跟进 5/13,漏 js_created'], ['C Chrome 可见性', '跟进 1/13,漏 skip_link 这类屏幕外的正常链接']], ['C Chrome 可见性'])),
    step("robots.txt 写了 Disallow: /trap/。一个页面有 9 个链接,其中 1 个是指向 /trap/ 的隐藏链接:urllib.robotparser.can_fetch 允许 8 个、禁止 1 个,被禁止的恰好就是 /trap/ 那一个。遵守 robots.txt 不需要去判断链接可不可见。", t=tl(S(3)), done=lidx(S(3), '页面里共 9 个链接'), b=bars([['页面里的链接', 9, '9'], ['robots 允许', 8, '8'], ['robots 禁止', 1, '1']], 10, done=[1], mark=[2]), kv=KV([['robots.txt', 'Disallow: /trap/'], ['can_fetch 允许', '8 个'], ['can_fetch 禁止', '1 个(/trap/)']], ['can_fetch 禁止'])),
    step("一个 60 页的合成站点(每页 8 个指向其他页面的真链接,另有 1 个 display:none 的 /trap/<页号> 链接),三种爬虫从 /p/0 出发各爬一遍:A 取全部 a[href]、不看 robots.txt:请求了 60 个真页面、60 个 /trap/ 页面;B 取全部 a[href]、遵守 robots.txt:60 个真页面、0 个 /trap/;C 用 Chrome 只跟进可见的链接:60 个真页面、0 个 /trap/(用时 3.8 秒,A 和 B 约 0.1 秒以内)。B 和 C 都爬全了真页面;B 比 C 快得多。", t=tl(S(4)), done=lidx(S(4), 'B 取全部 a[href],遵守'), mark=lidx(S(4), 'A 取全部 a[href],不看'), b=bars([['A:请求的 /trap/ 页面', 60, '60'], ['B:请求的 /trap/ 页面', 0, '0'], ['C:请求的 /trap/ 页面', 0, '0']], 64, mark=[0], done=[1, 2]), kv=KV([['A 不看 robots', '60 个真页面 + 60 个 /trap/'], ['B 遵守 robots', '60 个真页面 + 0 个 /trap/'], ['C Chrome 可见性', '60 个真页面 + 0 个 /trap/,用时 3.8 秒']], ['B 遵守 robots'])),
    step("站长在日志里看到的陷阱请求(爬虫 A):20 次里,从取到页面到请求陷阱链接的间隔中位 0.6 ms;陷阱请求都没有 Referer(20/20);UA 都是 python-requests/2.34.2。这么短的间隔、不带 Referer 的请求,能让站长把它和一个人在页面上点击区分开。这一节只是描述服务器端能看到什么,不是教你怎么避开它;避免的办法就是前几节的:遵守 robots.txt,只跟进人会看到的链接。", t=tl(S(5)), done=lidx(S(5), '取到页面之后'), b=bars([['取到页面到请求陷阱的间隔 ms(中位)', 0.6, '0.6'], ['没有 Referer 的陷阱请求', 20, '20/20']], 22, mark=[0], done=[1]), kv=KV([['间隔', '0.6 ms(中位)'], ['Referer', '20/20 都没有'], ['UA', 'python-requests/2.34.2']], ['间隔'])),
]
A = mkartp('p69', 69, '爬虫,蜜罐链接,隐藏链接,robots.txt,checkVisibility,lxml,Chrome,Python,真实验证,动画演示',
    '在本机页面上量隐藏链接:17 种写法里,静态解析全部跟进,加内联样式过滤后仍有 5 个被跟进,Chrome 可见性判断只跟进 1 个(文字与背景同色),但会漏掉屏幕外的无障碍链接;遵守 robots.txt 的 Disallow 就不会碰到 /trap/;陷阱请求和所在页面的间隔只有 0.6 ms。',
    '有的站点会在页面里放人看不到、但程序会取到的链接。谁会去访问它们?这篇在本机用 17 种隐藏写法逐个测:不同的爬虫写法各自会跟进哪些、会漏掉哪些,以及服务器日志里这种请求是什么样子。这是描述性的测量,不涉及怎么绕过它。',
    [('13 / 5 / 1', '17 种写法里人眼看不到的 13 个链接,静态全取 / 静态加内联过滤 / Chrome 可见性判断 各会跟进几个'), ('60 对 0', '60 页的合成站点上,不看 robots.txt 的爬虫请求的 /trap/ 页面数 与 遵守 robots.txt(或只跟进可见链接)的爬虫'), ('0.6 ms', '陷阱请求与所在页面的请求之间的间隔(中位)')],
    [('哪些写法会被哪种办法跟进', '<p>静态解析(lxml 取全部 a[href])会跟进所有人眼看不到的链接。再加对内联样式和 hidden 属性的正则过滤,仍会跟进 5 个:来自外部样式表的类、脚本加载后才隐藏的、noscript 里的、屏幕外的无障碍链接、文字与背景同色的——样式表里的规则和脚本的结果静态 HTML 里看不出来。</p>'),
     ('浏览器的判断', '<p>用真实的 Chrome 加载后,用 checkVisibility 加位置尺寸判断,只剩文字与背景同色的会被跟进。代价是更慢(60 页用 3.8 秒,静态解析不到 0.1 秒);并且会漏掉“跳到正文”这类平时在屏幕外、键盘聚焦才出现的无障碍链接,这是正常链接。</p>'),
     ('robots.txt', '<p>站点在 robots.txt 里 Disallow 的路径,遵守它的爬虫根本不会请求。实验里陷阱路径写在 Disallow 里,can_fetch 把它挡在外面,不需要判断可见性。</p>'),
     ('合成站点的结果', '<p>60 页的站点上,不看 robots.txt 的静态爬虫请求了 60 个 /trap/ 页面;遵守 robots.txt 的,和只跟进可见链接的 Chrome 爬虫,都是 0 个,而且都爬全了 60 个真页面。</p>'),
     ('站长看到什么', '<p>陷阱请求在取到页面后约 0.6 ms 就来了,不带 Referer,UA 是库的默认 UA。这样的请求很容易和人区分。这里只是描述,不是教怎么避开;避免的做法是遵守 robots.txt、只跟进人会看到的链接、遇到被禁止的路径就别去碰。</p>')],
    steps,
    [ENV_P + '。页面和站点都是本机服务器上的合成页面(17 种链接写法、60 页的站点、一个 Disallow: /trap/ 的 robots.txt);静态解析用 lxml,浏览器用 Chrome 154 通过 CDP(pcdp.py);各情形跑一次;“人眼能不能看到”是我按写法设的标签,没有真人看过;第一节的内联样式过滤是我写的正则,只是一种粗糙的静态启发式',
     '没有验证:真实站点上的蜜罐是怎么写的(这里的页面是我构造的);按鼠标行为、点击速度判断的检测;CSS 里用 clip-path、transform、z-index 遮盖等没有测的隐藏写法;文字与背景同色这种写法怎么被检测到(三种办法都没有);用真人浏览器点击与程序访问的比较;站点收到陷阱请求之后会做什么(封禁、限流、返回假数据),本机服务器没有实现这些'],
    '隐藏链接')
